create extension if not exists pgcrypto;
create table if not exists public.admins (id uuid primary key references auth.users(id) on delete cascade,name text not null default '',email text not null unique,role text not null default 'admin' check(role in ('super_admin','admin','editor')),status text not null default 'active' check(status in ('active','blocked')),created_at timestamptz not null default now());
create table if not exists public.users (id uuid primary key default gen_random_uuid(),name text not null default '',email text not null default '',phone text not null default '',profile_photo_url text not null default '',status text not null default 'active' check(status in ('active','blocked')),created_at timestamptz not null default now());
create table if not exists public.channels (id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',logo_url text not null default '',social_links jsonb not null default '{}'::jsonb,status text not null default 'active' check(status in ('active','inactive')),created_at timestamptz not null default now());
create table if not exists public.videos (id uuid primary key default gen_random_uuid(),title text not null,description text not null default '',thumbnail_url text not null default '',video_url text not null default '',category text not null default '',status text not null default 'draft' check(status in ('published','draft')),created_at timestamptz not null default now());
create table if not exists public.notices (id uuid primary key default gen_random_uuid(),title text not null,content text not null default '',status text not null default 'published' check(status in ('published','hidden')),created_at timestamptz not null default now());
create table if not exists public.site_settings (id integer primary key default 1 check(id=1),website_name text not null default 'Pro Income Administration',description text not null default '',logo_url text not null default '',contact_phone text not null default '',whatsapp text not null default '',facebook text not null default '',youtube text not null default '',tiktok text not null default '',telegram text not null default '',updated_at timestamptz not null default now());
insert into public.site_settings(id) values(1) on conflict(id) do nothing;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where id=auth.uid() and status='active'); $$;
alter table public.admins enable row level security; alter table public.users enable row level security; alter table public.channels enable row level security; alter table public.videos enable row level security; alter table public.notices enable row level security; alter table public.site_settings enable row level security;
drop policy if exists admins_read on public.admins; create policy admins_read on public.admins for select using(id=auth.uid() or public.is_admin());
drop policy if exists admins_manage on public.admins; create policy admins_manage on public.admins for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists users_manage on public.users; create policy users_manage on public.users for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists channels_public_read on public.channels; create policy channels_public_read on public.channels for select using(true);
drop policy if exists channels_admin_manage on public.channels; create policy channels_admin_manage on public.channels for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists videos_public_read on public.videos; create policy videos_public_read on public.videos for select using(true);
drop policy if exists videos_admin_manage on public.videos; create policy videos_admin_manage on public.videos for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists notices_public_read on public.notices; create policy notices_public_read on public.notices for select using(true);
drop policy if exists notices_admin_manage on public.notices; create policy notices_admin_manage on public.notices for all using(public.is_admin()) with check(public.is_admin());
drop policy if exists settings_public_read on public.site_settings; create policy settings_public_read on public.site_settings for select using(true);
drop policy if exists settings_admin_manage on public.site_settings; create policy settings_admin_manage on public.site_settings for all using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public) values('pia-media','pia-media',true) on conflict(id) do update set public=true;
drop policy if exists pia_media_read on storage.objects; create policy pia_media_read on storage.objects for select using(bucket_id='pia-media');
drop policy if exists pia_media_insert on storage.objects; create policy pia_media_insert on storage.objects for insert with check(bucket_id='pia-media' and public.is_admin());
drop policy if exists pia_media_update on storage.objects; create policy pia_media_update on storage.objects for update using(bucket_id='pia-media' and public.is_admin()) with check(bucket_id='pia-media' and public.is_admin());
drop policy if exists pia_media_delete on storage.objects; create policy pia_media_delete on storage.objects for delete using(bucket_id='pia-media' and public.is_admin());
